/**
 * Nullable sorting direction wrapper for optional sort parameters. This schema
 * enables endpoints to accept sorting direction values that can be explicitly
 * null, supporting cases where sort order is optional or client wants unsorted
 * results in analytics and data retrieval operations.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type INullableDirection = {
  /**
   * The optional sorting direction. Use 'asc' for ascending order or 'desc'
   * for descending order. Null indicates no specific sort direction.
   */
  value?: "asc" | "desc" | null | undefined;
};
